"""TranscriptMiner -- Mine Claude Code session history for usage patterns, mistakes, and automation candidates. Use when Kody says "audit my sessions", "what am I doing wrong in Claude Code", "usage audit", "mine my transcripts", "analyze my Claude Code history", "what should be a skill", or asks how he's using Claude Code across past sessions. Extracts tool stats, error signatures, Read:Edit ratios, my-message categories (corrections/rejections), and permission denials from ~/.claude/projects JSONL — with evidence, never vibes.

Generated by the rapp skill from transcript-miner. The RCI capsule at the bottom of this file carries the full original; `toast.py convert` restores it byte-exact."""

import json
import re
import sys

try:
    from agents.basic_agent import BasicAgent
except ImportError:  # running OUTSIDE the brainstem -- stay executable anyway.
    class BasicAgent:  # noqa: D101 - minimal stand-in, same contract
        def __init__(self, name=None, metadata=None):
            if name:
                self.name = name
            if metadata:
                self.metadata = metadata

        def perform(self, **kwargs):
            return "Not implemented."

        def system_context(self):
            return None

        def to_tool(self):
            return {"type": "function", "function": {
                "name": self.name,
                "description": self.metadata.get("description", ""),
                "parameters": self.metadata.get("parameters", {})}}

# The procedural layer, verbatim from the source capability. The brainstem
# returns this to the model, so the skill's instructions still drive behaviour
# -- now behind a typed, deterministic tool contract.
INSTRUCTIONS = '# transcript-miner\n\nTurns the raw `~/.claude/projects/<project>/<session>.jsonl` archive into a\nusage audit. One JSON message per line (type, content blocks, tool_use,\ntimestamps). Sessions are large — this NEVER reads whole transcripts into\ncontext; it runs a streaming extractor and returns aggregates.\n\n## Run it\n\n```\npython3 ~/.claude/skills/transcript-miner/scripts/mine.py --window 40 --json /tmp/audit.json\n```\n\nFlags: `--window N` (last N substantial sessions), `--min-bytes N` (size floor,\ndefault 200KB), `--project SUBSTR` (filter to one project), `--json OUT` (full\nper-session rows).\n\n## Turn signals into findings\n\nThe script gives you the numbers; you write the audit. Rules:\n- **Every claim cites a session file + excerpt.** No uncited findings.\n- **Rank by frequency × cost**, label single-anecdote vs recurring.\n- **Findings schema:** `{finding, evidence, frequency, impact, confidence, fix}`.\n- **Fixes are behavioral rules, not principles** — "never `cd`, pass absolute\n  paths" not "be tidy". Each recurring failure → one rule / skill / hook.\n- Read:Edit ratio: >6 = research-first (good), <2 = edit-first — but bulk\n  file-generation sessions (estate sweeps) skew it low legitimately; note that.\n- Always include a "could not verify / out of scope" section.\n\n## Output\n\nAn evidence-backed report + draft SKILL.md for the top skill candidates + hook\nconfigs for the top automations. See the P2 audit for the reference shape.'

# Ordered commands lifted verbatim from the capability's own documentation.
STEPS = [
    {
        "cmd": "python3 ~/.claude/skills/transcript-miner/scripts/mine.py --window 40 --json /tmp/audit.json",
        "line": 11
    }
]


class TranscriptMinerAgent(BasicAgent):
    def __init__(self):
        self.name = 'TranscriptMiner'
        self.metadata = {
        "name": "TranscriptMiner",
        "description": "Mine Claude Code session history for usage patterns, mistakes, and automation candidates. Use when Kody says \"audit my sessions\", \"what am I doing wrong in Claude Code\", \"usage audit\", \"mine my transcripts\", \"analyze my Claude Code history\", \"what should be a skill\", or asks how he's using Claude Code across past sessions. Extracts tool stats, error signatures, Read:Edit ratios, my-message categories (corrections/rejections), and permission denials from ~/.claude/projects JSONL \u2014 with evidence, never vibes.",
        "parameters": {
                "properties": {},
                "required": [],
                "type": "object"
        }
        }
        super().__init__(name=self.name, metadata=self.metadata)

    def perform(self, **kwargs):  # toaster:generated-perform
        missing = [k for k in self.metadata["parameters"].get("required", [])
                   if k not in kwargs]
        if missing:
            return json.dumps({"status": "error",
                               "missing_required": missing}, indent=2)
        resolved, unresolved = [], set()
        for step in STEPS:
            cmd = step["cmd"]
            for key, value in kwargs.items():
                for token in ("<" + key.replace("_", "-") + ">",
                              "<" + key + ">",
                              "{{" + key + "}}",
                              "$" + key.upper()):
                    cmd = cmd.replace(token, str(value))
            for leftover in re.findall(r"<[a-zA-Z][a-zA-Z0-9 _.-]{1,40}>", cmd):
                unresolved.add(leftover)
            resolved.append(cmd)
        return json.dumps({"status": "ok",
                           "steps": resolved,
                           "unresolved_placeholders": sorted(unresolved),
                           "note": "Resolved deterministically by the agent; "
                                   "run in order. Nothing was executed here."},
                          indent=2)

if __name__ == "__main__":
    # Standalone entry point: the deterministic layer runs with NO brainstem,
    # no framework, no install. This is what lets a "simple SKILL.md" platform
    # keep real determinism -- the host model shells out to this file instead
    # of improvising the procedure in prose.
    #     echo '{"arg": "value"}' | python3 transcript_miner_agent.py
    #     python3 transcript_miner_agent.py '{"arg": "value"}'
    #     python3 transcript_miner_agent.py --tool          # emit the JSON tool contract
    _a = sys.argv[1:]
    if _a and _a[0] == "--tool":
        print(json.dumps(TranscriptMinerAgent().to_tool(), indent=2))
    else:
        _raw = _a[0] if _a else (sys.stdin.read().strip() or "{}")
        print(TranscriptMinerAgent().perform(**json.loads(_raw)))

